package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
)

type StructSchema struct {
	Name  string `json:"name"`
 Fields []Field `json:"fields"`
}

type Field struct {
	Name   string `json:"name"`
	Type   string `json:"type"`
	Optional bool  `json:"optional"`
}

func parseGoFile(filename string) (StructSchema, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
	if err != nil {
		return StructSchema{}, fmt.Errorf("failed to parse %s: %w", filename, err)
	}
	ast.Walk(func(node ast.Node) error {
		switch n := node.(type) {
		case *ast.Field:
			fieldName := n.Name.Text
			fieldType := ""
			for _, p := range n.Type.Parts {
				if p == "string" || p == "int32" || p == "bool" {
					fieldType = p
				}
			}
			return nil
		default:
			return nil
		}
	}, file)
	return StructSchema{
		Name:  filename,
		Fields: []Field{},
	}, nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run script.go FILE_NAME STRUCT_NAME")
		os.Exit(1)
	}

	filename := os.Args[1]
	struct_name := os.Args[2]

	struct_schema, err := parseGoFile(filename)
	if err != nil {
		fmt.Printf("Error parsing %q: %v\n", filename, err)
		os.Exit(1)
	}

	schema, _ := json.MarshalIndent(struct_schema, "", "    ")
	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", struct_name), schema, 0644)
	if err != nil {
		fmt.Printf("Failed to save AVRO schema to %s.avsc: %v\n", struct_name, err)
	}
}
```

